<?php
use App\Models\CustomerPurchaseRequest; use App\Support\AuthorizationScope;
use function Livewire\Volt\computed; use function Livewire\Volt\layout; use function Livewire\Volt\state;
layout('layouts.app'); state(['status'=>'','search'=>'']);
$requests=computed(function(){ $user=auth()->user();$query=CustomerPurchaseRequest::withoutGlobalScopes()->with(['customer','branch'])->where('company_id',$user->company_id);if(AuthorizationScope::scopeFor($user,'report_scope',AuthorizationScope::BRANCH)!==AuthorizationScope::COMPANY)$query->where('branch_id',$user->branch_id);return $query->when($this->status,fn($q)=>$q->where('status',$this->status))->when($this->search,fn($q)=>$q->where(fn($s)=>$s->where('request_number','like',"%{$this->search}%")->orWhereHas('customer',fn($c)=>$c->where('name','like',"%{$this->search}%"))))->latest()->paginate(20);});
?>
<div><x-page-header title="Customer Requests" description="Review B2B portal requests and prepare quotations." :breadcrumbs="['Dashboard'=>route('dashboard'),'Customer Requests'=>null]"/><x-card><div class="mb-4 grid gap-3 sm:grid-cols-2"><input wire:model.live.debounce.300ms="search" placeholder="Request or customer" class="rounded-xl border-slate-200 dark:bg-navy-950"><select wire:model.live="status" class="rounded-xl border-slate-200 dark:bg-navy-950"><option value="">All statuses</option>@foreach(\App\Models\CustomerPurchaseRequest::STATUSES as $value)<option value="{{ $value }}">{{ str($value)->headline() }}</option>@endforeach</select></div><x-table :headers="['Request','Customer','Branch','Items','Submitted','Status','']">@forelse($this->requests as $request)<tr><td class="px-4 py-3 font-black">{{ $request->request_number }}</td><td class="px-4 py-3">{{ $request->customer->name }}</td><td class="px-4 py-3">{{ $request->branch?->name }}</td><td class="px-4 py-3">{{ $request->items()->count() }}</td><td class="px-4 py-3">{{ $request->submitted_at->format('d M Y H:i') }}</td><td class="px-4 py-3">{{ str($request->status)->headline() }}</td><td class="px-4 py-3"><a href="{{ route('customer-requests.show',$request) }}" wire:navigate class="font-bold text-build-orange">Review</a></td></tr>@empty<tr><td colspan="7" class="px-4 py-10 text-center text-slate-500">No customer requests found.</td></tr>@endforelse</x-table><div class="mt-4">{{ $this->requests->links() }}</div></x-card></div>
